create database customer_behaviour;
use customer_behaviour;
show tables;

select*from customers limit 10;


-- Q1. What is the total revenue generated by male vs. female customers?
select gender,sum(purchase_amount)as total_puchase_amount_by_gender
from customers
group by gender;

-- Q2. Which customers used a discount but still spent more than the average purchase amount?
select customer_id,purchase_amount,discount_applied
from customers 
where discount_applied='yes' and purchase_amount>
(
select avg(purchase_amount)as avg_purchase_amount
from customers
);

-- Q3. Which are the top 5 products with the highest average review rating?
select item_purchased,round(avg(review_rating),2)as average_product_ratings
from customers
group by item_purchased
order by average_product_ratings desc
limit 5;

-- Q4. Compare the average Purchase Amounts between Standard and Express Shipping.
select shipping_type,round(avg(purchase_amount),2)
from customers
where shipping_type in ('standard','express')
group by shipping_type;

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.
select subscription_status,count(customer_id)as total_customers ,
round(avg(purchase_amount),2)as avg_spent,
round(sum(purchase_amount),2)as total_revenue
from customers
group by subscription_status
order by total_revenue,avg_spent;

-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?
select item_purchased,discount_rate,rank_top5_discount
from(
select item_purchased,discount_rate,
dense_rank() over(order by discount_rate desc) as rank_top5_discount
from
(
select item_purchased,
round(sum(case when discount_applied = 'yes' then 1 else 0 end)/count(*)*100,2) as discount_rate
from customers
group by item_purchased)x)y
where rank_top5_discount  <= 5;

-- Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment.
select segment_customers,count(segment_customers)
from 
(
select customer_id,previous_purchases,
case 
when previous_purchases <= 1 then 'new'
when previous_purchases <= 10 then 'returning'
when previous_purchases <= 50 then 'loyal'
end as segment_customers
from customers
order by previous_purchases desc)x
group by segment_customers;



-- Q8. What are the top 3 most purchased products within each category?
select category,item_purchased,total_orders,top3_product_by_category_wise
from
(
select category,item_purchased,total_orders,
row_number() over (partition by category order by total_orders desc)as top3_product_by_category_wise
from
(
select category,item_purchased,count(customer_id)total_orders
from customers 
group by category,item_purchased
order by category
)x)y
where  top3_product_by_category_wise <= 3;


-- Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select count(customer_id)as repeat_buyers,subscription_status
from customers
where previous_purchases>5 
group by subscription_status;

select * from customers;

-- Q10. What is the revenue contribution of each age group?
select age_group,sum(purchase_amount)as contribution_by_age_group 
from customers
group by age_group
order by  contribution_by_age_group desc ;
